--- 序列任务类似于一个 "并且 "的操作。只要它的一个子任务返回失败，它就会返回失败。
--- 如果一个子任务返回成功，那么它将依次运行下一个任务。
--- 如果所有子任务都返回成功，那么它将返回成功。

------------ import ------------
local Composite = import("Frame.AI.BT.Composites.Composite")
------------ import ------------

------------ define ------------
local TaskStatus = Composite.TaskStatus
------------ define ------------

---@class Sequence
local Sequence = Class("Sequence", Composite)

function Sequence:__init(abortType)
    Composite.__init(self)

    self._abortType = abortType or Composite.AbortTypes.None
    
end

function Sequence:__delete()

end

function Sequence:Update(context)
    --- 首先，如果我们不在第一个子节点身上，我们就处理条件性中止
    if not Composite.IsFirstIndex(self) then
        self:HandleConditionalAborts(context)
    end

    local current = self._children[self._currentChildIndex]
    local status  = current:Tick(context)
    
    if status ~= TaskStatus.Success then
        return status
    end
    
    self._currentChildIndex = self._currentChildIndex + 1

    if self._currentChildIndex > #self._children then
        Composite.ResetCurrentIndex(self)
        return TaskStatus.Success
    end

    return TaskStatus.Running
end

function Sequence:HandleConditionalAborts(context)
    --- 检查任何较低优先级的任务，看它们是否改变为成功
    if self._hasLowerPriorityConditionalAbort then
        Composite.UpdateLowerPriorityAbortConditional(self, context, TaskStatus.Success)
    end

    if Composite.BTUtils.HasAbortType(self._abortType, Composite.AbortTypes.Self) then
        Composite.UpdateSelfAbortConditional(self, context, TaskStatus.Success)
    end
end


return Sequence
 